mapper.select:
SELECT distinct a.id, a.`code`, a.type, a.`status`, a.source_warehouse, a.target_warehouse, a.create_name, a.create_time, a.update_time, a.affirm_name, a.affirm_time, note FROM wms_transfer_slip a LEFT JOIN wms_transfer_slip_info b ON b.transfer_slip_id = a.id
a.del_flag = 0
and a.code LIKE CONCAT('%',#{dto.code},'%')
and b.material_name LIKE CONCAT('%',#{dto.materialName},'%')
and b.material_code LIKE CONCAT('%',#{dto.materialCode},'%')
AND a.status = #{dto.status}
and a.type = #{dto.type}
and a.source_warehouse = #{dto.sourceWarehouse}
and a.target_warehouse = #{dto.targetWarehouse}
and b.source_shelf_name LIKE CONCAT('%',#{dto.sourceShelfName},'%')
and b.source_shelf_code LIKE CONCAT('%',#{dto.sourceShelfCode},'%')
and b.target_shelf_name LIKE CONCAT('%',#{dto.targetShelfName},'%')
and b.target_shelf_code LIKE CONCAT('%',#{dto.targetShelfCode},'%')
and b.batch LIKE CONCAT('%',#{dto.batch},'%')
and b.case_no LIKE CONCAT('%',#{dto.caseNo},'%')
and a.create_name LIKE CONCAT('%',#{dto.createName},'%')
and a.affirm_name LIKE CONCAT('%',#{dto.affirmName},'%')
and a.create_time BETWEEN #{dto.createStartTime} and #{dto.createEndTime}
and a.affirm_time BETWEEN #{dto.affirmStartTime} and #{dto.affirmEndTime}
ORDER BY a.update_time DESC

select info.material_id, sum(quantity) as quantity  from wms_transfer_slip wts join wms_transfer_slip_info info on wts.id = info.transfer_slip_id and info.del_flag = 0
where wts.del_flag = 0

    and wts.source_warehouse in

        #{id}

    or wts.target_warehouse in

        #{id}



    and wts.affirm_time between #{startTime} and #{endTime}

and wts.`status` in(1,2,3)
group by info.material_id;

SELECT wtsi.material_name, sum(wtsi.quantity) quantity FROM wms_transfer_slip_info wtsi LEFT JOIN wms_transfer_slip wts ON wts.id = wtsi.transfer_slip_id WHERE wts.del_flag = 0 and wts.source_warehouse = #{id} and wts.create_time between #{startTime} and #{endTime} and wtsi.material_name in
#{name}
GROUP BY wtsi.material_name

SELECT wtsi.material_id, wtsi.unit, wts.create_time, sum(wtsi.quantity) quantity FROM wms_transfer_slip_info wtsi LEFT JOIN wms_transfer_slip wts ON wts.id = wtsi.transfer_slip_id WHERE wts.del_flag = 0 and wtsi.target_shelf in
#{warehouseId}
and wtsi.material_id in
#{materialId}
GROUP BY wtsi.unit, wts.create_time, wtsi.material_id

SELECT DATE_FORMAT( wts.create_time, '%Y-%m-%d' ) field1, wtsi.material_id field2, sum( wtsi.quantity ) field3, wtsi.unit field4 FROM wms_transfer_slip_info wtsi LEFT JOIN wms_transfer_slip wts ON wts.id = wtsi.transfer_slip_id WHERE wts.del_flag = 0 and wtsi.target_shelf in
#{warehouseId}
and wtsi.material_id in
#{materialId}
and wts.create_time BETWEEN #{start} and #{end} GROUP BY wtsi.unit, field1, wtsi.material_id

SELECT DATE_FORMAT( wts.create_time, '%Y-%m' ) field1, wtsi.material_id field2, sum( wtsi.quantity ) field3, wtsi.unit field4 FROM wms_transfer_slip_info wtsi LEFT JOIN wms_transfer_slip wts ON wts.id = wtsi.transfer_slip_id WHERE wts.del_flag = 0 and wtsi.target_shelf in
#{warehouseId}
and wtsi.material_id in
#{materialId}
and wts.create_time BETWEEN #{start} and #{end} GROUP BY wtsi.unit, field1, wtsi.material_id

SELECT DATE_FORMAT( wts.create_time, '%Y' ) field1, wtsi.material_id field2, sum( wtsi.quantity ) field3, wtsi.unit field4 FROM wms_transfer_slip_info wtsi LEFT JOIN wms_transfer_slip wts ON wts.id = wtsi.transfer_slip_id WHERE wts.del_flag = 0 and wtsi.target_shelf in
#{warehouseId}
and wtsi.material_id in
#{materialId}
and wts.create_time BETWEEN #{start} and #{end} GROUP BY wtsi.unit, field1, wtsi.material_id
